package app.forjadecolor.domain.paints

import app.forjadecolor.domain.ForjaJson
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonPrimitive
import java.text.Normalizer

/**
 * One paint of the catalogue: the lists of Vallejo, Citadel and Army Painter saved in the app and searched
 * before the AI. Generated by tools/gen-catalogue.py from Arcturus5404/miniature-paints (MIT, see
 * catalogue-LICENSE.txt); the same file ships in the PWA. Colours are approximate.
 */
data class CatalogueEntry(
    val brand: String,
    /** Maker's code; Citadel sells by name, so there the name is the code. */
    val code: String,
    val nameEn: String,
    val range: String,
    val type: PaintType,
    val hex: String,
)

val CATALOGUE: List<CatalogueEntry> by lazy {
    val text = CatalogueEntry::class.java.getResourceAsStream("/catalogue.json")!!.use { it.readBytes().decodeToString() }
    (ForjaJson.parseToJsonElement(text) as JsonObject)["paints"]!!.let { it as JsonArray }.map { row ->
        val (brand, code, nameEn, range, type, hex) = (row as JsonArray).map { it.jsonPrimitive.content }
        CatalogueEntry(brand, code, nameEn, range, PaintType.valueOf(type.uppercase()), hex)
    }
}

private operator fun <T> List<T>.component6(): T = this[5]

/** Lower case, no accents, single spaces: how names and queries are compared. */
private fun fold(s: String): String =
    Normalizer.normalize(s, Normalizer.Form.NFD).replace(Regex("\\p{M}+"), "").lowercase().replace(Regex("\\s+"), " ").trim()

private fun compactCode(s: String) = fold(s).replace(Regex("[.\\s-]"), "")

// What people (and the AI) call these makers.
private val BRAND_ALIASES = mapOf(
    "vallejo" to "Vallejo", "acrylicos vallejo" to "Vallejo",
    "citadel" to "Citadel", "citadel colour" to "Citadel", "games workshop" to "Citadel", "gw" to "Citadel",
    "army painter" to "Army Painter", "the army painter" to "Army Painter",
)

fun catalogueBrand(brand: String): String? = BRAND_ALIASES[fold(brand)]

/** The catalogue entry for a brand and code (written any way: 72010, 72.010), else by brand and name. */
fun findInCatalogue(brand: String, code: String?, name: String? = null): CatalogueEntry? {
    val maker = catalogueBrand(brand) ?: return null
    val inBrand = CATALOGUE.filter { it.brand == maker }
    val c = code?.trim().orEmpty()
    if (c.isNotEmpty()) {
        val wanted = compactCode(normalizeCode(maker, c))
        inBrand.firstOrNull { compactCode(it.code) == wanted }?.let { return it }
    }
    val n = fold(name ?: c)
    return if (n.isEmpty()) null else inBrand.firstOrNull { fold(it.nameEn) == n || fold(it.code) == n }
}

/** Catalogue paints matching every word of the query in brand, code, name or range; exact codes first. */
fun searchCatalogue(query: String, limit: Int = 20): List<CatalogueEntry> {
    val words = fold(query).split(' ').filter { it.isNotEmpty() }
    if (words.isEmpty()) return emptyList()
    val q = compactCode(query)
    fun rank(e: CatalogueEntry) = when {
        compactCode(e.code) == q -> 0
        fold(e.nameEn).startsWith(fold(query)) -> 1
        else -> 2
    }
    return CATALOGUE
        .filter { e ->
            val hay = fold("${e.brand} ${e.code} ${e.nameEn} ${e.range}")
            words.all { w -> w in hay || w.replace(Regex("[.\\s-]"), "") in compactCode(e.code) }
        }
        .sortedBy(::rank)
        .take(limit)
}

/**
 * A paint from a catalogue entry. Spanish name: the one given, else the seed's for the BSL codes, else
 * the English name (the catalogue has no Spanish names).
 */
fun paintFromCatalogue(e: CatalogueEntry, spanishName: String? = null): Paint {
    val seed = SEED_INVENTORY.findPaint(PaintRef(e.brand, e.code))
    val name = spanishName?.trim()?.ifEmpty { null } ?: seed?.name ?: e.nameEn
    return Paint(e.brand, e.code, name, e.range, e.type, e.hex, nameEn = e.nameEn)
}

/** A scanned paint after the catalogue check; [fromCatalogue] when its data comes from the catalogue. */
data class CatalogueLookup(val paint: Paint, val fromCatalogue: Boolean)

/**
 * A paint read from a photo, checked in the catalogue first: when found, the catalogue's code, English
 * name, range, type and colour win, and a Spanish name the AI gave is kept. Same rule as the PWA.
 */
fun lookUpInCatalogue(p: Paint): CatalogueLookup {
    val e = findInCatalogue(p.brand, p.code, p.name) ?: return CatalogueLookup(p, false)
    // The AI's name is Spanish only when it differs from the English names.
    val spanish = if (listOfNotNull(e.nameEn, p.nameEn).any { fold(it) == fold(p.name) }) null else p.name
    return CatalogueLookup(paintFromCatalogue(e, spanish), true)
}
